          ]
        },
        {
          "proposicao": "A escolha do tipo de ancoragem é apresentada como dependente da geometria das linhas e principalmente do tipo de embarcação e de operação, da quantidade de risers, do custo e da profundidade do mar; o trecho classifica as linhas em catenária convencional, raio curto taut leg e ancoragens verticais com tendões.",
          "trechos": [
            "E256ac88faae72067:1398:2098",
            "E256ac88faae72067:2098:2167"
          ],
          "condicoes": [
            "contexto de estruturas offshore e ancoragem de unidades flutuantes"
          ],
          "limites": [
